/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::Goose,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".goose/skills")),
            user_path: Some(PathBuf::from(".config/goose/skills")),
            also_reads_from: vec![PathBuf::from(".claude/skills"), PathBuf::from(".agents/skills")],
            notes: None,
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &["license", "compatibility", "metadata", "allowed-tools"],
                "claudine/docs/cross-referencing/goose.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Mcp),
            repo_path: Some(PathBuf::from("")),
            user_path: Some(PathBuf::from("")),
            also_reads_from: vec![],
            notes: Some("MCP-based commands, not file-based"),
            properties: None,
        },
        agents: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Yaml),
            repo_path: Some(PathBuf::from(".goose/recipes")),
            user_path: Some(PathBuf::from(".config/goose/recipes")),
            also_reads_from: vec![],
            notes: Some("Recipe YAML files with specific schema"),
            properties: Some(ResourcePropertySchema::new(
                &["title", "description"],
                &["instructions", "prompt", "extensions", "parameters", "sub_recipes"],
                "claudine/docs/cross-referencing/goose.md",
            )),
        },
        scripts: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Executable),
            repo_path: Some(PathBuf::from(".goose/scripts")),
            user_path: Some(PathBuf::from(".config/goose/scripts")),
            also_reads_from: vec![],
            notes: None,
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: true,
            compatibility: true,
            metadata: true,
            allowed_tools: true,
            user_invocable: false,
            disable_model_invocation: false,
        },
    }
}
